"use client";
import React, { useEffect } from "react";
import {
  addProductToCart,
  deleteProductFromCart,
  getCarrito,
} from "../Data/Cart"; // Importar las funciones para agregar, eliminar y obtener productos del carrito

interface Product {
  id: number; // Cambiar 'id' a tipo 'number'
  name: string;
  price: number;
  imageUrl: string;
  code: string;
}

interface NewProductsContainerProps {
  products: Product[];
  itemQuantity: number;
  setItemQuantity: React.Dispatch<React.SetStateAction<number>>;
  handleAddProduct: (productCode: string) => void;  // ✅ Agregado
  handleDeleteProduct: (productCode: string) => void;  // ✅ Agregado
}

const NewProductsContainer: React.FC<NewProductsContainerProps> = ({
  products,
  itemQuantity,
  setItemQuantity,
}) => {
  // Función para agregar un producto al carrito
  const handleAddToCart = (productCode: string) => {
    addProductToCart(productCode); // Llamada a la función para agregar el producto
    setItemQuantity(itemQuantity + 1); // Actualizar la cantidad de artículos en el carrito
  };

  // Función para eliminar un producto del carrito
  const handleRemoveFromCart = (productCode: string) => {
    deleteProductFromCart(productCode); // Llamada a la función para eliminar el producto
    setItemQuantity(itemQuantity - 1); // Actualizar la cantidad de artículos en el carrito
  };

  // Usamos un efecto para actualizar la cantidad total de productos en el carrito
  useEffect(() => {
    const totalQuantity = getCarrito().reduce(
      (sum, product) => sum + product.quantity,
      0
    );
    setItemQuantity(totalQuantity); // Actualizamos la cantidad total de productos en el carrito
  }, [itemQuantity, setItemQuantity]);

  return (
    <div>
      <h2>Productos</h2>
      {products.map((product) => (
        <div key={product.id}>
          <img src={product.imageUrl} alt={product.name} />
          <h3>{product.name}</h3>
          <p>Precio: ${product.price}</p>
          <button onClick={() => handleAddToCart(product.code)}>
            Agregar al carrito
          </button>
          <button onClick={() => handleRemoveFromCart(product.code)}>
            Eliminar del carrito
          </button>
        </div>
      ))}
    </div>
  );
};

export default NewProductsContainer;
