"use client";



import { useState, useEffect } from "react";

// Define the Product type
type Product = {
  id: number;
  code: string;
  name: string;
  price: number;
  imageUrl: string;
};
import { useTheme } from "./context/ThemeContext";
import NewHeader from "./alternateUI/NewHeader";
import NewProductsContainer from "./alternateUI/NewProductsContainer";
import NewCartModal from "./alternateUI/NewCartModal";
import UIChangerButton from "./Components/UIChangerButton";
import {
  addProductToCart,
  deleteProductFromCart,
  getCarrito,
} from "./Data/Cart";

// Simulación de productos disponibles en la tienda
const products: Product[] = [
  { id: 1, code: "P001", name: "Producto 1", price: 100, imageUrl: "/images/product1.jpg" },
  { id: 2, code: "P002", name: "Producto 2", price: 200, imageUrl: "/images/product2.jpg" },
  { id: 3, code: "P003", name: "Producto 3", price: 300, imageUrl: "/images/product3.jpg" },
];

export default function Home() {
  const [showCartResume, setShowCartResume] = useState(false);
  const [itemQuantity, setItemQuantity] = useState(0);
  const { isAlternateUI } = useTheme();

  const updateItemQuantity = () => {
    const carrito = getCarrito();
    const totalQuantity = carrito.reduce(
      (total, product) => total + product.quantity,
      0
    );
    setItemQuantity(totalQuantity);
  };

  const handleAddProduct = (productCode: string) => {
    addProductToCart(productCode);
    updateItemQuantity();
  };

  const handleDeleteProduct = (productCode: string) => {
    deleteProductFromCart(productCode);
    updateItemQuantity();
  };

  useEffect(() => {
    updateItemQuantity();
  }, []);

  return (
    <div className="App">
      <div className="contentPage">
        <UIChangerButton />
        {isAlternateUI ? (
          <>
            <NewHeader
              setShowCartResume={setShowCartResume}
              itemQuantity={itemQuantity}
            />
            <NewProductsContainer
              products={products} // ✅ Se pasa la prop requerida
              itemQuantity={itemQuantity}
              setItemQuantity={setItemQuantity}
              handleAddProduct={handleAddProduct}
              handleDeleteProduct={handleDeleteProduct}
            />
            {showCartResume && (
              <NewCartModal
                handleClose={() => setShowCartResume(false)}
                handleDeleteProduct={handleDeleteProduct}
                products={products} // 🔥 Se agrega la prop `products`
              />
            )}
          </>
        ) : (
          <div>UI Predeterminada</div>
        )}
      </div>
    </div>
  );
}
